import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-120-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-120-0.md","lastUpdated":1787058499000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-120-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.120.0<br><strong>Release Date:</strong> 12 August 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Deprecate use of Basic Authentication, (GLU-3081)</li><li>Clipboard Copy Confirmation (GLU-3140)</li><li>Ability to Copy the Agent Card URL (GLU-3184)</li><li>JWT Bearer Grant Connections (GLU-3191)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed JSON Content Type Handling (GLU-3225)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="deprecate-use-of-basic-authentication-glu-3081" tabindex="-1">Deprecate use of Basic Authentication, (GLU-3081) <a class="header-anchor" href="#deprecate-use-of-basic-authentication-glu-3081" aria-label="Permalink to “Deprecate use of Basic Authentication, (GLU-3081)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>We are phasing out Basic Authentication so users will no longer be able to select Basic Authentication as an auth method for new connections via the UI, reducing reliance on a weaker authentication method across the platform.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When setting up new AireGlu Endpoints, you&#39;ll be guided towards more secure authentication options instead of Basic Authentication. Existing endpoints will still be able to use it as to not break backwards compatibility.</p></div><h4 id="clipboard-copy-confirmation-glu-3140" tabindex="-1">Clipboard Copy Confirmation (GLU-3140) <a class="header-anchor" href="#clipboard-copy-confirmation-glu-3140" aria-label="Permalink to “Clipboard Copy Confirmation (GLU-3140)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Copy-to-clipboard buttons now display a toast notification to confirm when content has been successfully copied.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You&#39;ll get instant, clear feedback whenever you copy something to your clipboard, so you know it&#39;s worked without needing to check.</p></div><h4 id="ability-to-copy-the-agent-card-url-glu-3184" tabindex="-1">Ability to Copy the Agent Card URL (GLU-3184) <a class="header-anchor" href="#ability-to-copy-the-agent-card-url-glu-3184" aria-label="Permalink to “Ability to Copy the Agent Card URL (GLU-3184)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Added a copy button for the agent card endpoint URL, consistent with the existing options to copy endpoint and MCP server URLs.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now quickly copy an agent&#39;s card URL to share or reuse elsewhere, without having to construct or note it down manually.</p></div><h4 id="jwt-bearer-grant-connections-glu-3191" tabindex="-1">JWT Bearer Grant Connections (GLU-3191) <a class="header-anchor" href="#jwt-bearer-grant-connections-glu-3191" aria-label="Permalink to “JWT Bearer Grant Connections (GLU-3191)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Added support for a new JWT Bearer Grant connection type, alongside the existing Client Credentials connection options, enabling authentication to APIs such as Google that require this grant type.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now set up connections to services that require JWT Bearer authentication, widening the range of external systems you can integrate with.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-json-content-type-handling-glu-3225" tabindex="-1">Fixed JSON Content Type Handling (GLU-3225) <a class="header-anchor" href="#fixed-json-content-type-handling-glu-3225" aria-label="Permalink to “Fixed JSON Content Type Handling (GLU-3225)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where responses with a content type of <code>application/vnd.api+json</code> were not recognised as valid JSON and were instead interpreted as a stream, leading to unexpected results.</p></div>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};